def as_json_table_type(x: DtypeObj) -> str:
    """
    Convert a NumPy / pandas type to its corresponding json_table.

    Parameters
    ----------
    x : np.dtype or ExtensionDtype

    Returns
    -------
    str
        the Table Schema data types

    Notes
    -----
    This table shows the relationship between NumPy / pandas dtypes,
    and Table Schema dtypes.

    ==============  =================
    Pandas type     Table Schema type
    ==============  =================
    int64           integer
    float64         number
    bool            boolean
    datetime64[ns]  datetime
    timedelta64[ns] duration
    object          str
    categorical     any
    =============== =================
    """
    import pandas as pd

    def is_integer_dtype(x):
        return pd.api.types.is_integer_dtype(x)

    def is_bool_dtype(x):
        return pd.api.types.is_bool_dtype(x)

    def is_numeric_dtype(x):
        return pd.api.types.is_numeric_dtype(x)

    def is_string_dtype(x):
        return pd.api.types.is_string_dtype(x)

    if is_integer_dtype(x):
        return "integer"
    elif is_bool_dtype(x):
        return "boolean"
    elif is_numeric_dtype(x):
        return "number"
    elif pd.api.types.is_datetime64_any_dtype(x):
        return "datetime"
    elif pd.api.types.is_timedelta64_dtype(x):
        return "duration"
    elif pd.api.types.is_extension_type(x):
        return "any"
    elif is_string_dtype(x):
        return "string"
    else:
        return "any"

